        static ImageList Images(int size=16){var images=new ImageList{ImageSize=new Size(size,size),ColorDepth=ColorDepth.Depth32Bit};foreach(string name in new[]{"folder","file","archive","image","text"}){var bitmap=new Bitmap(size,size);using(var g=Graphics.FromImage(bitmap)){g.SmoothingMode=SmoothingMode.AntiAlias;using(var brush=new SolidBrush(name=="folder"?Color.FromArgb(255,191,28):name=="archive"?Color.FromArgb(20,128,216):Color.FromArgb(130,155,177))){if(name=="folder"){g.FillRectangle(brush,1,5,size-2,size-6);g.FillRectangle(brush,2,2,size/2,6);}else{g.FillRectangle(brush,3,1,size-6,size-2);using(var pen=new Pen(Color.White))for(int y=4;y<size-3;y+=4)g.DrawLine(pen,5,y,size-5,y);}}}images.Images.Add(name,bitmap);}return images;}
        void BuildWelcome(){welcome.Dock=DockStyle.Fill;welcome.BackColor=Color.White;var title=new Label{Text=Edition.Name,Font=new Font("Segoe UI",Edition.Paid?26:38),ForeColor=Color.FromArgb(17,127,216),AutoSize=true,Location=new Point(45,40)};var description=new Label{Text="压缩 · 解压 · 无广告",AutoSize=true,Location=new Point(50,115)};var open=new Button{Text="打开压缩文件…",Name="welcome-open",Size=new Size(160,38),Location=new Point(50,160)};open.Click+=async(s,e)=>await Execute("open");var create=new Button{Text="新建压缩文件…",Size=new Size(160,38),Location=new Point(225,160)};create.Click+=async(s,e)=>await Execute("new");var tips=new Label{Text="拖入压缩包浏览，拖入文件或文件夹压缩\n\nZIP · 7Z · RAR · TAR · ISO",AutoSize=true,ForeColor=Color.DimGray,Location=new Point(50,225)};if(Edition.Paid){var license=new Button{Text="激活 / 授权与设备…",Size=new Size(190,34),Location=new Point(50,305)};license.Click+=async(s,e)=>await Execute("license");welcome.Controls.Add(license);}welcome.Controls.AddRange(new Control[]{title,description,open,create,tips});}
        internal void ApplyPreferences(){
            ArchiveEngine.AllowLongPaths=preferences.Bool("longPaths");backend.Dispatch("settings",new object[]{Json.Obj("rememberHistory",preferences.Bool("rememberHistory"),"openAfterExtract",preferences.Bool("openAfterExtract"),"defaultFormat",preferences.Str("defaultFormat"),"defaultLevel",preferences.Int("defaultLevel"))});
            files.View=preferences.Str("view")=="icons"?View.LargeIcon:View.Details;split.Panel1Collapsed=!preferences.Bool("tree");menus.RenderMode=preferences.Bool("elegant")?ToolStripRenderMode.Professional:ToolStripRenderMode.System;
            if(split.Width>300)split.SplitterDistance=Math.Max(100,Math.Min(split.Width-170,split.Width*preferences.Int("split")/100));StyleDialog(this);RebuildColumns();UpdateTitle();if(!backend.Busy)AcquireArchive();UpdateCommands();
        }
        void RebuildColumns(){files.BeginUpdate();files.Columns.Clear();var selected=Json.Strings(preferences.Values,"columns");for(int i=0;i<FieldKeys.Length;i++)if(i==0||selected.Contains(FieldKeys[i]))files.Columns.Add(new ColumnHeader{Text=FieldNames[i],Tag=FieldKeys[i],Width=i==0?270:i==4?145:110,TextAlign=i==1||i==2?HorizontalAlignment.Right:HorizontalAlignment.Left});files.EndUpdate();if(columnsMenu!=null)foreach(ToolStripMenuItem item in columnsMenu.DropDownItems)item.Checked=selected.Contains(item.Name.Substring(7));if(visible!=null)files.Invalidate();}
        ListViewItem Row(J entry){var row=new ListViewItem{Tag=entry,Text=Json.Str(entry,"name"),ImageKey=Json.Bool(entry,"isDirectory")?"folder":new[]{".png",".jpg",".gif",".bmp"}.Contains(Path.GetExtension(Json.Str(entry,"path")).ToLowerInvariant())?"image":"file"};foreach(ColumnHeader column in files.Columns.Cast<ColumnHeader>().Skip(1))row.SubItems.Add(Value(entry,Convert.ToString(column.Tag)));row.ImageIndex=files.SmallImageList.Images.IndexOfKey(row.ImageKey);return row;}
        static string Value(J entry,string field){switch(field){case "size":case "packed":return Json.Bool(entry,"isDirectory")?"":!Json.Bool(entry,field+"Known",true)?"未知":SizeText(Json.Num(entry,field));case "type":return Json.Bool(entry,"isDirectory")?"文件夹":Path.GetExtension(Json.Str(entry,"path")).TrimStart('.').ToUpperInvariant()+" 文件";case "encryption":return Json.Str(entry,"encryption",Json.Bool(entry,"encrypted")?"已加密":"");case "extra":return Json.Str(entry,"extra");default:return Json.Str(entry,field);}}
        internal static string SizeText(long bytes){return bytes>=1073741824?(bytes/1073741824d).ToString("0.##")+" GB":bytes>=1048576?(bytes/1048576d).ToString("0.##")+" MB":bytes>=1024?(bytes/1024d).ToString("0.##")+" KB":bytes+" B";}
        internal async Task OpenArchive(string path,string secret="",int page=0){
            if(backend.Busy&&archive!=null&&Json.Str(archive,"path")==path){message.Text="任务完成后再刷新压缩包";return;}ReleaseArchive();if(listing!=null)listing.Cancel();var current=listing=new CancellationTokenSource();message.Text="正在读取 "+Path.GetFileName(path)+"…";UseWaitCursor=true;string retrySecret=null;
            try{
                var data=await Task.Run(()=>backend.Engine.List(path,secret,current.Token,null,page));current.Token.ThrowIfCancellationRequested();
                if(Json.Str(data,"type").Equals("zip",StringComparison.OrdinalIgnoreCase)){try{var metadata=await Task.Run(()=>ArchiveTools.ZipMetadata(path,page));foreach(var e in Json.Array(Json.Get(data,"entries")).Select(Json.Map)){var m=Json.Map(Json.Get(metadata,Json.Str(e,"path").TrimEnd('/')));foreach(var pair in m)e[pair.Key]=pair.Value;}}catch(ArchiveError){}catch(DecoderFallbackException){}}
                if(current!=listing||closing)return;archive=data;password=secret;codePage=page;folder="";filter="";search.Text="";entries=Json.Array(Json.Get(data,"entries")).Select(Json.Map).ToList();BuildTree();welcome.Visible=false;split.Visible=true;UpdateTitle();RefreshFiles();
                // Remember on the same backend path as the previous interface.
                backend.RememberOpened(data);UpdateRecent();message.Text="已就绪";
            }catch(OperationCanceledException){}catch(ArchiveError error){if(error.Code=="PASSWORD_REQUIRED"){string value=Prompt("输入密码",Path.GetFileName(path),"",true);retrySecret=value;}else Error(error);}catch(Exception error){Error(error);}finally{if(current==listing){UseWaitCursor=false;if(!backend.Busy)AcquireArchive();}}
            if(retrySecret!=null)await OpenArchive(path,retrySecret,page);
        }
        void ReleaseArchive(){if(archiveLease!=null){archiveLease.Dispose();archiveLease=null;}}
        void AcquireArchive(){ReleaseArchive();if(archive!=null&&!preferences.Bool("allowExternalDelete")&&File.Exists(Json.Str(archive,"path")))archiveLease=new FileStream(Json.Str(archive,"path"),FileMode.Open,FileAccess.Read,FileShare.ReadWrite);}
        void UpdateTitle(){Text=archive==null?Edition.Name:(preferences.Bool("fullTitle")?Json.Str(archive,"path"):Json.Str(archive,"name"))+" - "+Edition.Name;}
        void BuildTree(){changingTree=true;tree.BeginUpdate();tree.Nodes.Clear();nodes.Clear();var root=new TreeNode(Json.Str(archive,"name")){Tag="",ImageKey="archive",SelectedImageKey="archive"};tree.Nodes.Add(root);nodes[""]=root;
            foreach(var entry in entries){string path=Json.Str(entry,"path").TrimEnd('/');var parts=path.Split('/');int count=Json.Bool(entry,"isDirectory")?parts.Length:parts.Length-1;if(count>128)continue;string parent="";for(int i=0;i<count;i++){string current=parent+parts[i]+"/";if(!nodes.ContainsKey(current)){var node=new TreeNode(parts[i]){Tag=current,ImageKey="folder",SelectedImageKey="folder"};nodes[parent].Nodes.Add(node);nodes[current]=node;}parent=current;}}
            tree.SelectedNode=root;root.Expand();if(preferences.Bool("autoExpand")&&nodes.Count<=2000)tree.ExpandAll();tree.EndUpdate();changingTree=false;
        }
        static string ParentFolder(string path){var parts=path.TrimEnd('/').Split('/').ToList();if(parts.Count>0)parts.RemoveAt(parts.Count-1);return parts.Count==0?"":String.Join("/",parts)+"/";}
        void GoFolder(string path){folder=path;filter="";search.Text="";if(nodes.ContainsKey(path)){changingTree=true;tree.SelectedNode=nodes[path];tree.SelectedNode.EnsureVisible();changingTree=false;}RefreshFiles();}
        internal void RefreshFiles(){
            if(archive==null){visible.Clear();files.VirtualListSize=0;UpdateCommands();return;}var byPath=new Dictionary<string,J>(StringComparer.OrdinalIgnoreCase);
            foreach(var entry in entries){string path=Json.Str(entry,"path");if(filter.Length>0){if(path.IndexOf(filter,StringComparison.OrdinalIgnoreCase)>=0)byPath[path]=entry;continue;}if(!path.StartsWith(folder,StringComparison.Ordinal))continue;string relative=path.Substring(folder.Length).TrimEnd('/');if(relative.Length==0)continue;int slash=relative.IndexOf('/');if(slash>=0){string child=relative.Substring(0,slash),key=folder+child;byPath[key]=Json.Obj("path",key,"name",child,"isDirectory",true,"virtual",true);}else byPath[path.TrimEnd('/')]=entry;}
            IEnumerable<J> ordered=byPath.Values;Func<J,object> field=e=>sortColumn==1||sortColumn==2?(object)Json.Num(e,FieldKeys[sortColumn]):Value(e,FieldKeys[sortColumn]);ordered=sortDescending?ordered.OrderBy(e=>!Json.Bool(e,"isDirectory")).ThenByDescending(field):ordered.OrderBy(e=>!Json.Bool(e,"isDirectory")).ThenBy(field);
            visible=ordered.ToList();if(folder!=""&&filter=="")visible.Insert(0,Json.Obj("path",ParentFolder(folder),"name","..","isDirectory",true,"parent",true));files.SelectedIndices.Clear();files.VirtualListSize=visible.Count;files.Invalidate();summary.Text="文件: "+entries.Count(e=>!Json.Bool(e,"isDirectory"))+"  文件夹: "+Math.Max(0,nodes.Count-1)+"  压缩文件大小: "+SizeText(Json.Num(archive,"archiveSize"));UpdateCommands();
        }
        internal J[] Selected(){return files.SelectedIndices.Cast<int>().Where(i=>i<visible.Count&&!Json.Bool(visible[i],"parent")).Select(i=>visible[i]).ToArray();}
        string[] SelectedPaths(){var result=new HashSet<string>();foreach(var entry in Selected()){string path=Json.Str(entry,"path").TrimEnd('/');foreach(var e in entries)if(Json.Str(e,"path").TrimEnd('/')==path||Json.Bool(entry,"isDirectory")&&Json.Str(e,"path").StartsWith(path+"/",StringComparison.Ordinal))result.Add(Json.Str(e,"path"));}return result.ToArray();}
        bool Editable(){return archive!=null&&!Json.Bool(archive,"encrypted")&&codePage==0&&new[]{"zip","7z"}.Contains(Json.Str(archive,"type").ToLowerInvariant());}
        bool Allowed(string id){if(id=="license")return Edition.Paid;if(new[]{"open","new","new-window","admin-window","settings","exit","help","about","tasks","batch","repair","recover","fields","details","icons","tree"}.Contains(id))return true;if(archive==null)return false;if(new[]{"add","paste","rename","delete"}.Contains(id)&&(!Editable()||backend.Busy))return false;if(new[]{"open-entry","preview"}.Contains(id)&&files.SelectedIndices.Count==0)return false;if(new[]{"rename","delete","copy-files","copy-path","extract-selected"}.Contains(id)&&Selected().Length==0)return false;if(id=="rename"&&Selected().Length!=1)return false;if(id=="comment"&&(Json.Str(archive,"type").ToLowerInvariant()!="zip"||backend.Busy))return false;if(new[]{"save-as","delete-archive","delete-permanent","close-archive"}.Contains(id)&&backend.Busy)return false;return true;}
        void UpdateCommands(){if(pagesMenu!=null)foreach(var item in pagesMenu.DropDownItems.OfType<ToolStripMenuItem>())if(item.Name.StartsWith("page-"))item.Checked=item.Name=="page-"+codePage;foreach(var pair in commands)pair.Value.Enabled=Allowed(pair.Key);foreach(var pair in tools)pair.Value.Enabled=Allowed(pair.Key);if(archive!=null&&Selected().Length>0)message.Text="已选择 "+Selected().Length+" 项";if(commands.ContainsKey("tree"))commands["tree"].Checked=preferences.Bool("tree");}
        void ShowHome(){ReleaseArchive();archive=null;password="";codePage=0;folder="";entries.Clear();visible.Clear();files.VirtualListSize=0;tree.Nodes.Clear();split.Visible=!preferences.Bool("startPage");welcome.Visible=preferences.Bool("startPage");summary.Text="无广告 · 本地处理";message.Text="已就绪";searchBar.Visible=false;UpdateTitle();UpdateCommands();}
        void UpdateRecent(){recentMenu.DropDownItems.Clear();var recent=Json.Array(Json.Get(backend.Dispatch("init",new object[0]),"recent"));foreach(var r in recent.Select(Json.Map)){string path=Json.Str(r,"path");var item=new ToolStripMenuItem(Json.Str(r,"name")){ToolTipText=path};item.Click+=async(s,e)=>await OpenArchive(path);recentMenu.DropDownItems.Add(item);}if(recent.Length==0)recentMenu.DropDownItems.Add(new ToolStripMenuItem("暂无记录"){Enabled=false});var clear=new ToolStripMenuItem("清空历史记录");clear.Click+=(s,e)=>{backend.Dispatch("clear-history",new object[0]);UpdateRecent();};recentMenu.DropDownItems.Add(new ToolStripSeparator());recentMenu.DropDownItems.Add(clear);}
        async Task Guard(Func<Task> action){try{await action();}catch(OperationCanceledException){message.Text="已取消";}catch(Exception error){Error(error);}}
        void Error(Exception error){message.Text=error.Message;if(Environment.GetEnvironmentVariable("NZIP_TEST_MODE")=="1")return;if(Edition.Paid&&error is ArchiveError&&((ArchiveError)error).Code=="LICENSE_REQUIRED"){using(var dialog=new LicenseWindow())dialog.ShowDialog(this);return;}MessageBox.Show(this,error.Message,Edition.Name,MessageBoxButtons.OK,MessageBoxIcon.Warning);}
        internal async Task Execute(string id){await Guard(async()=>{
            if(!Allowed(id))return;if(new[]{"new","extract","extract-selected","add","paste","rename","delete","test","scan","comment","copy-files","preview","batch","repair","recover"}.Contains(id))LicenseGate.Capture();switch(id){
                case "license":using(var dialog=new LicenseWindow())dialog.ShowDialog(this);break;
                case "open":using(var dialog=new OpenFileDialog{Title="打开压缩文件",Filter=ArchiveFormats.OpenFilter})if(dialog.ShowDialog(this)==DialogResult.OK)await OpenArchive(dialog.FileName);break;
                case "new":CreateArchive(new string[0]);break;case "close-archive":if(listing!=null)listing.Cancel();ShowHome();break;
                case "save-as":await SaveAs();break;case "delete-archive":case "delete-permanent":DeleteArchive(id=="delete-permanent");break;
                case "reveal":backend.Dispatch("reveal",new object[]{Json.Str(archive,"path")});break;
                case "test":case "scan":StartJob(id,Payload());break;case "extract":case "extract-selected":ExtractDialog(id=="extract-selected"?SelectedPaths():new string[0]);break;
                case "new-window":case "admin-window":Process.Start(new ProcessStartInfo(Application.ExecutablePath,"--new-window"){UseShellExecute=true,Verb=id=="admin-window"?"runas":"open"});break;
                case "exit":Close();break;case "add":AddDialog();break;case "rename":Rename();break;case "delete":DeleteEntries();break;case "comment":CommentDialog();break;
                case "copy-files":await CopyFiles();break;case "paste":if(Clipboard.ContainsFileDropList())AddSources(Clipboard.GetFileDropList().Cast<string>().ToArray());else message.Text="剪贴板中没有文件，请在资源管理器复制文件后粘贴";break;
                case "copy-path":Clipboard.SetText(String.Join("\r\n",Selected().Select(e=>Json.Str(archive,"path")+"\\"+Json.Str(e,"path").Replace('/','\\'))));break;
                case "select-all":for(int i=0;i<visible.Count;i++)if(!Json.Bool(visible[i],"parent"))files.SelectedIndices.Add(i);break;case "invert":for(int i=0;i<visible.Count;i++)if(!Json.Bool(visible[i],"parent")){if(files.SelectedIndices.Contains(i))files.SelectedIndices.Remove(i);else files.SelectedIndices.Add(i);}break;
                case "search":searchBar.Visible=true;search.Focus();break;case "settings":using(var settings=new SettingsWindow(this,backend,preferences))if(settings.ShowDialog(this)==DialogResult.OK){ApplyPreferences();if(archive!=null){BuildTree();RefreshFiles();}else ShowHome();}break;
                case "details":case "icons":preferences.Values["view"]=id;preferences.Save();files.View=id=="details"?View.Details:View.LargeIcon;break;
                case "tree":preferences.Values["tree"]=!preferences.Bool("tree");preferences.Save();split.Panel1Collapsed=!preferences.Bool("tree");UpdateCommands();break;
                case "refresh":await OpenArchive(Json.Str(archive,"path"),password,codePage);break;case "open-entry":await OpenEntry();break;case "preview":await Preview();break;case "properties":PropertiesDialog();break;
                case "tasks":ShowTasks();break;case "batch":BatchDialog();break;case "repair":RepairDialog();break;case "recover":RecoverDialog();break;
                case "help":ShowText("使用说明","快捷键与菜单与截图保持一致。双击文件夹浏览目录层级，双击文件解压临时副本并用本地程序打开（文本使用记事本）。临时副本的修改不会自动写回压缩包。可选的内置内容预览位于视图菜单。\r\n\r\n修改支持默认代码页下未加密 ZIP / 7Z。解压使用新目录，保留现有内容。\r\n\r\nZIP 修复恢复完整的 Store/Deflate 条目，输出新包，原文件保留；不支持加密、ZIP64 或分卷修复。密码恢复支持 ZIP / 7Z 的本地字典或指定字符范围，最多 100 万候选、30 分钟，可取消，不保证成功。\r\n\r\n扫描需可用的 AMSI 引擎。Windows 11 右键子菜单位于显示更多选项。详细说明见程序目录 USAGE.txt。\r\n\r\n许可请参阅程序目录 LICENSE、COMMERCIAL-TERMS-DRAFT.txt（收费版）及 7zip 目录。","help");break;
                case "about":ShowText("关于 "+Edition.Name,Edition.Name+" "+typeof(Program).Assembly.GetName().Version.ToString(3)+"\r\n原生 Windows 界面 · C# / .NET Framework 4.8\r\n无广告。程序使用官方 7-Zip 引擎。\r\n本地开发版本尚未代码签名。"+(Edition.Paid?"\r\n客户编号："+Json.Str(LicenseRuntime.Current.Status(),"customerRef")+"\r\n首次联网激活后永久离线可用。":""),"about");break;
            }
        });}
        J Payload(){return Json.Obj("archive",Json.Str(archive,"path"),"password",password,"codePage",codePage,"checkSpace",preferences.Bool("checkSpace"),"preallocate",preferences.Bool("preallocate"));}
        internal string StartJob(string kind,J payload){if(new[]{"modify","comment"}.Contains(kind))ReleaseArchive();if(kind=="create"){payload["threads"]=preferences.Int("threads");payload["sharedFiles"]=preferences.Bool("sharedFiles");}var result=backend.Dispatch("start-job",new object[]{kind,payload});if(preferences.Bool("modalProgress"))ShowTasks();return Json.Str(result,"id");}
        void ShowTasks(){if(taskWindow==null||taskWindow.IsDisposed){taskWindow=new TaskWindow(backend);StyleDialog(taskWindow);}if(!taskWindow.Visible)taskWindow.Show(this);taskWindow.Activate();UpdateJobs();}
        void UpdateJobs(){var state=backend.Dispatch("init",new object[0]);var jobs=Json.Array(Json.Get(state,"jobs")).Select(Json.Map).ToArray();if(taskWindow!=null&&!taskWindow.IsDisposed)taskWindow.UpdateJobs(jobs);var active=jobs.FirstOrDefault(j=>new[]{"running","cancelling","queued"}.Contains(Json.Str(j,"status")));progress.Visible=active!=null;if(active!=null){progress.Value=Math.Max(0,Math.Min(100,(int)Json.Num(active,"percent")));message.Text=Json.Str(active,"label")+" · "+Json.Str(active,"status")+" "+progress.Value+"%";}
            foreach(var job in jobs.Where(j=>new[]{"completed","failed","cancelled"}.Contains(Json.Str(j,"status"))))if(completed.Add(Json.Str(job,"id"))){var result=Json.Map(Json.Get(job,"result"));message.Text=Json.Str(job,"status")=="completed"?Json.Str(result,"message","任务完成"):Json.Str(job,"error","已取消");if(Json.Str(job,"type")=="recover"&&Json.Str(job,"status")=="completed")ShowText("密码恢复结果",Json.Str(backend.Dispatch("take-password",new object[]{Json.Str(job,"id")}),"password"),"password-result",true);if(new[]{"modify","comment"}.Contains(Json.Str(job,"type"))&&archive!=null&&!backend.Busy){string current=folder;var open=OpenArchive(Json.Str(archive,"path"),password,codePage);open.ContinueWith(t=>Ui(()=>GoFolder(nodes.ContainsKey(current)?current:"")));}}
            UpdateCommands();
        }
        Task HandleLaunch(J request){return Guard(()=>HandleLaunchCore(request));}
        async Task HandleLaunchCore(J request){if(request==null)return;if(Json.Str(request,"type")!="open")LicenseGate.Capture();string path=Json.Str(request,"path");switch(Json.Str(request,"type")){case "open":await OpenArchive(path);break;case "extract":await OpenArchive(path);if(archive!=null)ExtractDialog(new string[0]);break;case "extract-folder":backend.Dispatch("extract-folder",new object[]{path,"",0});ShowTasks();break;case "compress":CreateArchive(new[]{path});break;}}
        void ListenPipe(){while(!closing){try{using(var server=new NamedPipeServerStream(pipeName,PipeDirection.In)){pipe=server;server.WaitForConnection();using(var reader=new StreamReader(server)){var line=reader.ReadLine();if(line==null)continue;var request=Program.LaunchRequest(Json.Strings(Json.Decode(line),"args"));Ui(async()=>{if(WindowState==FormWindowState.Minimized)WindowState=FormWindowState.Normal;Activate();await HandleLaunch(request);});}}}catch(IOException){}catch(ObjectDisposedException){break;}}}
        async void OnClosing(object sender,FormClosingEventArgs e){if(backend.Busy){e.Cancel=true;if(exitPending)return;if(MessageBox.Show(this,"还有任务未完成，取消任务并退出？临时文件将被清理。","NZIP",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;exitPending=true;backend.CancelAll();while(backend.Busy)await Task.Delay(30);Close();}}
        sealed class RibbonButton:Button {readonly string kind,label;bool hover;public RibbonButton(string kind,string label){this.kind=kind;this.label=label;FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;BackColor=Color.FromArgb(22,133,223);ForeColor=Color.White;AccessibleName=label;MouseEnter+=(s,e)=>{hover=true;Invalidate();};MouseLeave+=(s,e)=>{hover=false;Invalidate();};SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.Opaque|ControlStyles.ResizeRedraw,true);}
            protected override void OnPaint(PaintEventArgs e){
                // Each buffered frame must cover every pixel. Transparent Button backgrounds
                // replay the parent's paint with an offset, leaving stale icon/text pixels.
                var background=new Rectangle(0,Parent==null?0:-Top,Math.Max(1,Width),Math.Max(1,Parent==null?Height:Parent.ClientSize.Height));
                using(var gradient=new LinearGradientBrush(background,Color.FromArgb(70,161,234),Color.FromArgb(15,121,217),90f))e.Graphics.FillRectangle(gradient,ClientRectangle);
                e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;if(hover&&Enabled)using(var fill=new SolidBrush(Color.FromArgb(45,Color.White)))e.Graphics.FillRectangle(fill,ClientRectangle);using(var pen=new Pen(Enabled?Color.White:Color.FromArgb(135,210,245),1.35f)){
                int x=Width/2-15,y=14;if(kind=="pages"){e.Graphics.DrawEllipse(pen,x,y,31,31);e.Graphics.DrawEllipse(pen,x+9,y,13,31);e.Graphics.DrawLine(pen,x,y+16,x+31,y+16);e.Graphics.DrawLine(pen,x+3,y+7,x+28,y+7);e.Graphics.DrawLine(pen,x+3,y+24,x+28,y+24);}else if(kind=="fields"){for(int n=0;n<3;n++){e.Graphics.DrawRectangle(pen,x,y+n*12,3,3);e.Graphics.DrawLine(pen,x+8,y+n*12+1,x+31,y+n*12+1);}}else if(kind=="test")e.Graphics.DrawLines(pen,new[]{new Point(x+17,y),new Point(x+3,y+19),new Point(x+15,y+19),new Point(x+8,y+36),new Point(x+31,y+12),new Point(x+18,y+12),new Point(x+25,y)});else if(kind=="scan"){e.Graphics.DrawPolygon(pen,new[]{new Point(x+15,y),new Point(x+32,y+8),new Point(x+28,y+25),new Point(x+15,y+37),new Point(x+2,y+25),new Point(x-2,y+8)});e.Graphics.DrawLines(pen,new[]{new Point(x+7,y+16),new Point(x+13,y+23),new Point(x+24,y+11)});}else{e.Graphics.DrawLines(pen,new[]{new Point(x+2,y+34),new Point(x+2,y),new Point(x+22,y),new Point(x+31,y+9),new Point(x+31,y+34),new Point(x+2,y+34)});e.Graphics.DrawLines(pen,new[]{new Point(x+22,y),new Point(x+22,y+9),new Point(x+31,y+9)});if(kind=="add"||kind=="delete"){e.Graphics.DrawLine(pen,x+8,y+22,x+25,y+22);if(kind=="add")e.Graphics.DrawLine(pen,x+16,y+14,x+16,y+30);}else if(kind=="open")e.Graphics.DrawLines(pen,new[]{new Point(x+6,y+24),new Point(x+24,y+24),new Point(x+18,y+17),new Point(x+24,y+24),new Point(x+18,y+31)});else for(int n=0;n<7;n++)e.Graphics.DrawLine(pen,x+12+(n%2)*3,y+4+n*4,x+18+(n%2)*3,y+4+n*4);}}
                TextRenderer.DrawText(e.Graphics,label,Font,new Rectangle(0,57,Width,22),Enabled?Color.White:Color.FromArgb(170,220,250),TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}
        }
    }
}
